import numpy as np, json
m = np.load('model.npz'); W1,b1,W2,b2 = m['W1'],m['b1'],m['W2'],float(m['b2'])
f = json.load(open('features.json')); names=[x['name'] for x in f]
np.set_printoptions(precision=3, suppress=True, linewidth=200)
imp = np.abs(W2[:,None]*W1).sum(0); sgn=(W2[:,None]*W1).sum(0)
groups = {'vitals_last':range(0,8),'labs_last':range(8,34),'n_meas':range(34,68),'demo/context':range(68,75)}
for g,r in groups.items():
    r=list(r); print(g, 'imp sum', imp[r].sum().round(2), 'signed sum', sgn[r].sum().round(2))
print('\nn_meas features signed:')
for i in range(34,68): print(f'{names[i]:28s} imp={imp[i]:.2f} signed={sgn[i]:+.2f}')
print('\ncontext:')
for i in range(68,75): print(f'{names[i]:28s} imp={imp[i]:.2f} signed={sgn[i]:+.2f}')
# gradient sign consistency: fraction of neuron-wise contributions agreeing with sign
cons = np.abs(sgn)/imp
print('\nsign consistency of top features:')
for i in np.argsort(-imp)[:20]: print(f'{names[i]:28s} cons={cons[i]:.2f}')
# cosine similarity of flag column with others
Wn = W1/np.linalg.norm(W1,axis=0,keepdims=True)
cs = Wn.T@Wn[:,74]
for i in np.argsort(-np.abs(cs))[:10]: print(names[i], cs[i].round(2))
